import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        String s = sc.next();
        int T = 1;
        while (T-- > 0) {
            int ans;
            if (s.length() == 1) {
                char ch = s.charAt(0);
                ans = (ch == '0' || ch == '_' || ch == 'X') ? 1 : 0;
            } else {
                boolean xPresent = false;
                for (int i = 0; i < s.length(); i++) if (s.charAt(i) == 'X') xPresent = true;
                if (!xPresent) {
                    ans = solve(s);
                } else {
                    ans = 0;
                    for (int d = 0; d < 10; d++) {
                        String t = s.replace('X', (char)('0' + d));
                        ans += solve(t);
                    }
                }
            }
            pw.println(ans);
        }
        pw.close();
    }

    static int solve(String s) {
        int n = s.length();
        int ways = s.charAt(0) == '0' ? 0 : 1;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                if (i == 0) ways *= 9;
                else ways *= 10;
            }
        }
        char a = s.charAt(n - 2);
        char b = s.charAt(n - 1);
        int lastTwo;
        if (a == '_' && b == '_') {
            lastTwo = n == 2 ? 3 : 4;
        } else if (b == '_') {
            lastTwo = (a == '0' || a == '2' || a == '5' || a == '7') ? 1 : 0;
        } else if (a == '_') {
            if (b == '0') lastTwo = n == 2 ? 1 : 2;
            else if (b == '5') lastTwo = 2;
            else lastTwo = 0;
        } else {
            int val = Integer.parseInt(s.substring(n - 2));
            lastTwo = val % 25 == 0 ? 1 : 0;
        }
        return ways * lastTwo;
    }
}
